import { dirname } from "path";
import { fileURLToPath } from "url";
import { FlatCompat } from "@eslint/eslintrc";

const __filename = fileURLToPath(import.meta.url);
const __dirname = dirname(__filename);

const compat = new FlatCompat({
  baseDirectory: __dirname,
});

const eslintConfig = [
  ...compat.extends("next/core-web-vitals", "next/typescript"),
  {
    ignores: [
      "node_modules/**",
      ".next/**",
      "out/**",
      "build/**",
      "next-env.d.ts",
      // Generated by next-pwa at build time - not source we maintain.
      "public/sw.js",
      "public/workbox-*.js",
    ],
  },
  {
    // Build scripts under scripts/ are CommonJS on purpose: package.json has
    // no "type": "module", so these .js files run under Node's CJS loader and
    // `require()` is the correct form. The TS-style rule does not apply.
    files: ["scripts/**"],
    rules: {
      "@typescript-eslint/no-require-imports": "off",
    },
  },
];

export default eslintConfig;
